import React, { useState, useEffect } from 'react';
import './Quiz.css';

const quizData = [
  {id: 1, question: "Молодой человек влюблен в женщину. Как относиться к сексуальным отношениям до брака?", answers: [{text: "Телесные отношения сами по себе не грех, если они основаны на любви. Форма брака менее важна, чем содержание отношений.", tradition: "christianity"}, {text: "Сексуальные отношения вне брака — грех. Брак устанавливает правила и границы. Это дисциплина, которая укрепляет связь.", tradition: "islam"}]},
  {id: 2, question: "У вашей веры есть пищевые запреты. Вы в гостях и хозяйка готовила запретные блюда.", answers: [{text: "Всякая пища чиста, если вы благодарны. Отказ обидит хозяйку. Важно единство и любовь, а не правила о еде.", tradition: "christianity"}, {text: "Вышний установил четкие правила о еде. Вежливо откажитесь. Истинный верующий держит границы везде.", tradition: "islam"}]},
  {id: 3, question: "Супруг(а) узнает о неверности партнера. Как должна быть наказана неверность?", answers: [{text: "Прежде чем судить, вспомните свои грехи. Нужна честная беседа. Цель — восстановление, а не унижение.", tradition: "christianity"}, {text: "Неверность — тяжелый грех. Наказание должно быть справедливым. Общество должно знать о нарушении.", tradition: "islam"}]},
  {id: 4, question: "Вы должны молиться в определенное время, но работа требует внимания точно в этот момент.", answers: [{text: "Молитва — это внутреннее общение. Если вы молитесь в сердце во время работы, это считается. Не театр.", tradition: "christianity"}, {text: "Молитва — святой долг, установленный Вышним. Её время не выбирается. Прерывите дела и молитесь вовремя.", tradition: "islam"}]},
  {id: 5, question: "Женщина желает быть учителем или духовным лидером общины.", answers: [{text: "Если женщина обладает мудростью — она может учить и руководить кем угодно. Способность лидера определяется качеством духа, не полом.", tradition: "christianity"}, {text: "Мужчины и женщины имеют разные роли — это божественный порядок. Руководство общиной — мужская ответственность.", tradition: "islam"}]},
  {id: 6, question: "На торжестве предлагают напиток с алкоголем.", answers: [{text: "Вино само по себе не грех. Грех — пьянство. Пейте в меру, если это приносит радость. Единство важнее.", tradition: "christianity"}, {text: "Алкоголь — яд, помутняющий ум. Вышний запретил его полностью. Откажитесь. Это дисциплина веры.", tradition: "islam"}]},
  {id: 7, question: "Общество содержит рабов. Как относиться к этому институту?", answers: [{text: "Рабство противно природе человека. Каждый человек — брат вам. Вы должны освобождать рабов, платить им за труд.", tradition: "christianity"}, {text: "Рабство — реальность. Вышний регулирует его справедливыми правилами: рабы имеют право на отдых, пищу, безопасность.", tradition: "islam"}]},
  {id: 8, question: "Вы тяжело болеете. Врач предлагает лечение, но оно нарушает веру.", answers: [{text: "Вышний дал разум и науку. Забота о здоровье — долг перед Вышним. Следуйте врачу. Вышний желает вашего здоровья.", tradition: "christianity"}, {text: "Если лечение нарушает закон Вышнего, вы не можете его использовать. Молитесь и ищите альтернативы.", tradition: "islam"}]},
  {id: 9, question: "Вы разбогатели честным путем. Вокруг много нищих.", answers: [{text: "Богатство само по себе не грех. Но привязанность к деньгам — грех. Щедро раздавайте нуждающимся.", tradition: "christianity"}, {text: "Богатство — благословение. Вы имеете право на плоды труда. Но отчисляйте часть в поддержку нуждающихся — это долг.", tradition: "islam"}]},
  {id: 10, question: "Супруги несчастны друг с другом и причиняют друг другу боль. Могут ли они расстаться?", answers: [{text: "Если отношения причиняют боль, расставание может быть единственным честным путем. Лучше правда, даже если горька.", tradition: "christianity"}, {text: "Развод допустим, но это последняя мера. Сначала попытайтесь примирение. Развод совершается по установленным правилам.", tradition: "islam"}]},
  {id: 11, question: "Человек совершил убийство. Какое наказание справедливо?", answers: [{text: "Прощение выше справедливости. Цель — преобразование, не мщение. Если раскаялся, дайте возможность измениться.", tradition: "christianity"}, {text: "Закон справедлив для всех. Убийца должен понести справедливое возмездие. Это восстанавливает баланс.", tradition: "islam"}]},
  {id: 12, question: "Маленькая ложь спасет невинного. Правда разрушит жизнь доброго человека.", answers: [{text: "Если правда причинит вред, а ложь спасет невинного — выбирайте ложь. Вышний видит ваше сердце и мотивы.", tradition: "christianity"}, {text: "Ложь запрещена всегда. Нет условий для лжи. Если люди начнут лгать 'во благо', общество разрушится.", tradition: "islam"}]},
  {id: 13, question: "Есть науки, которые противоречат традиционным учениям. Нужно ли их изучать?", answers: [{text: "Истина везде. Наука не враг вере — она раскрывает величие творения. Изучайте смело. Вера не боится вопросов.", tradition: "christianity"}, {text: "Слишком много знаний отвлекает от главного — исполнения закона. Не теряйтесь в философиях, подвергающих основы веры.", tradition: "islam"}]},
  {id: 14, question: "Вы совершаете доброе дело. Есть возможность это скрыть или показать людям.", answers: [{text: "Делайте добро в тайне. Если делаете ради похвалы, вы уже получили награду. Истинное благочестие — в сердце.", tradition: "christianity"}, {text: "Пусть добро будет видно как пример для других. Люди должны видеть вашу преданность и подражать ей.", tradition: "islam"}]},
  {id: 15, question: "Как понимать вечность? Что происходит после смерти?", answers: [{text: "Если ваше сердце открыто Вышнему — вы соединены с Ним. После смерти вечная жизнь. Живите в любви, не в страхе.", tradition: "christianity"}, {text: "После смерти вас ждет суд. Вышний спросит о каждом деле. Эта жизнь — испытание. Живите с сознанием суда.", tradition: "islam"}]},
  {id: 16, question: "Ваш близкий друг — атеист и не верит в Бога. Как с ним общаться?", answers: [{text: "Любите его искренне. Молитесь за него с надеждой. Ваш пример жизни важнее слов. Не навязывайте веру, уважайте его выбор.", tradition: "christianity"}, {text: "Не будьте агрессивны, но приглашайте его к Истине с мудростью. Уважайте как человека. Только Вышний судит веру. Оказывайте помощь и поддержку.", tradition: "islam"}]},
  {id: 17, question: "Человек исповедует другую религию. Можно ли дружить и работать с ним?", answers: [{text: "Да, абсолютно. Любовь к ближнему не зависит от его веры. Истинный верующий любит всех людей, независимо от убеждений.", tradition: "christianity"}, {text: "Можно сотрудничать, но дружба должна быть осторожной. Не перенимайте их убеждения. Старайтесь оказать положительное влияние.", tradition: "islam"}]},
  {id: 18, question: "Иноверец попросил у вас помощь в беде. Ваши действия?", answers: [{text: "Помогите без колебаний. Сострадание не имеет границ веры. Это возможность показать силу вашей веры через доброту.", tradition: "christianity"}, {text: "Помогите из сострадания. Это долг перед человечеством. Но не поддерживайте его неверие. Помощь и истина могут идти вместе.", tradition: "islam"}]},
  {id: 19, question: "Ваш ребенок влюбился в человека другой веры. Как реагировать?", answers: [{text: "Если это любовь и взаимное уважение — благословите их. Вера не должна разлучать людей. Любовь может привести к духовному пробуждению.", tradition: "christianity"}, {text: "Не одобряйте такую связь. Брак между верующим и неверующим — источник разногласий. Убедите ребенка найти партнера своей веры.", tradition: "islam"}]},
  {id: 20, question: "На работе вас просят участвовать в праздновании, которое противоречит вашей вере.", answers: [{text: "Участвуйте с уважением. Единство и любовь важнее обрядов. Ваше присутствие показывает открытость и благожелательность.", tradition: "christianity"}, {text: "Вежливо откажитесь и объясните причину. Ваша вера — приоритет. Люди должны уважать ваш выбор и границы.", tradition: "islam"}]},
  {id: 21, question: "Атеист критикует вашу веру, называет её суеверием. Как ответить?", answers: [{text: "Не оспаривайте агрессивно. Ответьте с любовью и мудростью. Покажите силу веры своей жизнью, а не аргументами.", tradition: "christianity"}, {text: "Уверенно защитите веру фактами и логикой. Атеист должен услышать правду. Но делайте это с достоинством, не с гневом.", tradition: "islam"}]},
  {id: 22, question: "Общество требует отречься от веры ради социального успеха. Ваш выбор?", answers: [{text: "Никогда не отрекайтесь. Вера выше успеха. Лучше потерять все земное, чем изменить сердцу. Истинный верующий готов на жертву.", tradition: "christianity"}, {text: "Держитесь веры любой ценой. Компромисс в вере — предательство. Терпите трудности, но не отступайте от Истины.", tradition: "islam"}]},
  {id: 23, question: "Человек другой веры спасает вашу жизнь ценой своей. Как вы это воспринимаете?", answers: [{text: "Это акт любви и самопожертвования. Высшая ценность любви выше различий вер. Такой человек — святой, независимо от его убеждений.", tradition: "christianity"}, {text: "Это похвально и благородно. Вышний ценит такие поступки. Но это не делает его веру истинной. Уважайте его, но не переходите в его веру.", tradition: "islam"}]},
  {id: 24, question: "Нужно ли агитировать людей переходить в вашу веру?", answers: [{text: "Делитесь верой только когда просят. Личный пример и любовь — главные инструменты. Насильственное обращение противно сути веры.", tradition: "christianity"}, {text: "Да, нужно приглашать людей к Истине. Это долг верующего. Но делайте это мудро и с уважением, не грубо и не агрессивно.", tradition: "islam"}]},
  {id: 25, question: "После смерти атеист не верил. Где его душа? Как это должно влиять на ваше отношение к живым атеистам?", answers: [{text: "Только Вышний может судить душу. Вы не знаете, что было в его сердце. К живым атеистам относитесь с любовью и надеждой на их пробуждение.", tradition: "christianity"}, {text: "Он отошел от Истины и его судьба определена. Но это должно побуждать вас спешить спасать живых неверующих, пока не поздно.", tradition: "islam"}]}
];

function Quiz() {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [answers, setAnswers] = useState([]);
  const [showResult, setShowResult] = useState(false);
  const [shuffledQuestions, setShuffledQuestions] = useState([]);

  useEffect(() => {
    const shuffled = quizData.map(q => ({
      ...q,
      answers: Math.random() > 0.5 ? q.answers : [...q.answers].reverse()
    }));
    setShuffledQuestions(shuffled);
  }, []);

  const handleAnswer = (tradition) => {
    const newAnswers = [...answers, tradition];
    setAnswers(newAnswers);
    if (currentQuestion < shuffledQuestions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
    } else {
      setShowResult(true);
    }
  };

  const calculateResult = () => {
    const christianityCount = answers.filter(a => a === 'christianity').length;
    const islamCount = answers.filter(a => a === 'islam').length;
    return { christianityCount, islamCount };
  };

  const getResultText = () => {
    const { christianityCount, islamCount } = calculateResult();

    if (christianityCount > islamCount) {
      return {
        title: "Вам ближе Христианство",
        description: "Ваши убеждения совпадают с христианскими принципами. Вы цените благодать, прощение, внутреннее преобразование и личные отношения с Богом. Для вас важнее мотивация и честность сердца, чем буква закона. Вы верите в милосердие выше справедливости.",
        religion: "Христианство"
      };
    } else if (islamCount > christianityCount) {
      return {
        title: "Вам ближе Ислам",
        description: "Ваши убеждения совпадают с исламскими принципами. Вы цените порядок, четкие правила, дисциплину и справедливость. Для вас важны установленные законы и границы. Вы верите, что мораль должна быть ясной и одинаковой для всех. Регулярная практика и соблюдение предписаний — суть вашей веры.",
        religion: "Ислам"
      };
    } else {
      return {
        title: "Сбалансированная позиция",
        description: "Ваши убеждения в равной степени сочетают элементы обеих традиций. Вы цените как милосердие и внутреннее преобразование, так и дисциплину и справедливый закон. Вы гибки в подходе, но принципиальны в основах. Обе традиции находят отклик в вашем сердце.",
        religion: "Обе традиции"
      };
    }
  };

  const restartQuiz = () => {
    setCurrentQuestion(0);
    setAnswers([]);
    setShowResult(false);
  };

  if (shuffledQuestions.length === 0) {
    return <div className="loading">Загрузка...</div>;
  }

  if (showResult) {
    const result = getResultText();
    const { christianityCount, islamCount } = calculateResult();
    return (
      <div className="quiz-container">
        <div className="result-card">
          <h1>Результат теста</h1>
          <div className="score-display">
            <div className="score-item"><span className="score-label">Христианство</span><span className="score-value">{christianityCount}</span></div>
            <div className="score-divider"></div>
            <div className="score-item"><span className="score-label">Ислам</span><span className="score-value">{islamCount}</span></div>
          </div>
          <div className="result-content">
            <h2>{result.title}</h2>
            <p>{result.description}</p>
            <p style={{marginTop: '20px', fontSize: '1.2rem', fontWeight: 'bold', color: '#6EE7B7'}}>В вере вам ближе: {result.religion}</p>
          </div>
          <button onClick={restartQuiz} className="restart-btn">Пройти тест заново</button>
        </div>
      </div>
    );
  }

  const question = shuffledQuestions[currentQuestion];
  const progress = ((currentQuestion + 1) / shuffledQuestions.length) * 100;

  return (
    <div className="quiz-container">
      <div className="progress-bar"><div className="progress-fill" style={{ width: `${progress}%` }}></div></div>
      <div className="question-counter">Вопрос {currentQuestion + 1} из {shuffledQuestions.length}</div>
      <div className="question-card">
        <h2>{question.question}</h2>
        <div className="answers">
          {question.answers.map((answer, index) => (
            <button key={index} className="answer-btn" onClick={() => handleAnswer(answer.tradition)}>
              <span className="answer-label">Вариант {index === 0 ? 'A' : 'B'}</span>
              <p>{answer.text}</p>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Quiz;
